const input = $input.first()?.json ?? {};
const body = input.body ?? input;

return [{
  json: {
    config: {
      companyName: body.companyName || 'ABM Solutions Demo',
      senderName: body.senderName || 'Demo Sender',
      senderEmail: body.senderEmail || 'demo@example.com',
      slackWebhookUrl: body.slackWebhookUrl || 'REPLACE_WITH_SLACK_WEBHOOK_URL',
      hubspotToken: body.hubspotToken || 'REPLACE_WITH_HUBSPOT_PRIVATE_APP_TOKEN',
      openAiApiKey: body.openAiApiKey || 'REPLACE_WITH_OPENAI_API_KEY',
      demoMode: body.demoMode !== false
    },
    payload: body
  }
}];

const root=$input.first().json,p=root.payload||{};
const text=p.text||`INVOICE 1048
Vendor: Atlas Software LLC
Invoice Date: 2026-07-18
Due Date: 2026-08-17
Total Due: $4,250.00
Description: Annual automation platform subscription.
Payment terms: Net 30.`;
return [{json:{...root,document:{fileName:p.fileName||'invoice-1048.txt',text}}}];

const d=$input.first().json,text=d.document.text;
const type=/invoice/i.test(text)?'invoice':/agreement|contract/i.test(text)?'contract':/resume|experience/i.test(text)?'resume':'general';
const money=[...text.matchAll(/\$\s?[\d,]+(?:\.\d{2})?/g)].map(m=>m[0]);
const dates=[...text.matchAll(/\b\d{4}-\d{2}-\d{2}\b/g)].map(m=>m[0]);
const emails=[...text.matchAll(/[^\s@]+@[^\s@]+\.[^\s@]+/g)].map(m=>m[0]);
const lines=text.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);
return [{json:{...d,result:{documentType:type,fileName:d.document.fileName,entities:{amounts:money,dates,emails},keyLines:lines.slice(0,10),flags:{missingDate:dates.length===0,missingAmount:type==='invoice'&&money.length===0},processedAt:new Date().toISOString()}}}];
